const input=$input.first().json.body||$input.first().json; const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(!['Lead','Customer'].includes(input.entityType))throw new Error('entityType must be Lead or Customer');
if(!uuid.test(String(input.entityId||''))||!uuid.test(String(input.workflowRunId||'')))throw new Error('entityId and workflowRunId must be UUIDs');
return [{json:{entityType:input.entityType,entityId:input.entityId,workflowRunId:input.workflowRunId,requestedBy:input.requestedBy||null,requestedAt:input.requestedAt||new Date().toISOString()}}];

const request=$node['Code: Validate Entity Reference'].json;
const profile=$node['HTTP Request: Get Entity Profile'].json;
const intel=$node['HTTP Request: Get Qualification and Score'].json;
const interactions=$node['HTTP Request: Get Interaction History'].json;
const followup=$input.first().json;
const allowed=followup.allowedActions||followup.data?.allowedActions;
if(!Array.isArray(allowed)||allowed.length===0)throw new Error('Backend must supply a non-empty allowedActions list');
const evidence=[];
for(const x of (interactions.items||interactions.data?.items||[]).slice(0,30)){if(x.id)evidence.push({id:x.id,type:x.type||'INTERACTION',occurredAt:x.occurredAt||null,summary:String(x.subject||x.content||'').slice(0,300)});}
for(const k of ['qualificationId','scoreId'])if(intel[k])evidence.push({id:intel[k],type:k.toUpperCase()});
const candidateActions=allowed.slice(0,20).map(a=>({actionCode:a.actionCode,label:a.label,description:a.description||'',requiresApproval:Boolean(a.requiresApproval),evidenceIds:(a.evidenceIds||[]).filter(id=>evidence.some(e=>e.id===id))}));
const context={entityType:request.entityType,entityId:request.entityId,profile:profile.data||profile,intelligence:intel,followupSegment:followup,evidence,candidateActions};
const prompt=`Rank only the supplied candidateActions for this CRM entity. Do not invent actions or facts. Return JSON only: {"recommendations":[{"actionCode":"...","rank":1,"confidence":0.0,"explanation":"...","evidenceIds":["..."]}]}. Every evidenceIds value must come from supplied evidence. No execution instructions, no direct writes, no sending messages.\nCONTEXT=${JSON.stringify(context)}`;
return [{json:{...request,context,candidateActions,prompt}}];

const ai=$input.first().json||{}; const prep=$node['Code: Generate Candidate Actions'].json;
const t=ai.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||''; if(!t)throw new Error('Gemini returned no recommendations');
const clean=t.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();const parsed=JSON.parse(clean);
if(!Array.isArray(parsed.recommendations))throw new Error('recommendations must be an array');
const byCode=new Map(prep.candidateActions.map(a=>[a.actionCode,a]));const evidenceIds=new Set(prep.context.evidence.map(e=>e.id));
const recommendations=parsed.recommendations.slice(0,10).map(r=>{const c=byCode.get(r.actionCode);if(!c)throw new Error('AI proposed action outside backend allowlist: '+r.actionCode);if(!Array.isArray(r.evidenceIds)||r.evidenceIds.some(id=>!evidenceIds.has(id)))throw new Error('Recommendation contains unsupported evidence reference');if(typeof r.confidence!=='number'||r.confidence<0||r.confidence>1)throw new Error('Invalid recommendation confidence');return {actionCode:c.actionCode,rank:Number.isInteger(r.rank)&&r.rank>0?r.rank:99,confidence:r.confidence,explanation:String(r.explanation||'').slice(0,1000),evidenceIds:r.evidenceIds,requiresApproval:c.requiresApproval};}).sort((a,b)=>a.rank-b.rank);
if(!recommendations.length)throw new Error('No valid recommendations');
const humanApprovalRequired=recommendations.some(r=>r.requiresApproval||r.confidence<0.7);
return [{json:{...prep,recommendations,humanApprovalRequired,callbackPayload:{workflowRunId:prep.workflowRunId,entityType:prep.entityType,entityId:prep.entityId,recommendations,source:'AI_NEXT_BEST_ACTION',status:'COMPLETED'}}}];
